        "lingua_originale": "it",
        "titolo_orig": "Iran, Trump annuncia una tregua",
        "testo_it": "Trump annuncia una tregua di due settimane con l'Iran per avviare i negoziati.",
        "priorita": "Altissima",
        "id_gruppo": 1,
        "link": "https://ilmanifesto.it/iran-trump-annuncia-una-tregua",
